import{c as a,Q as o,j as e,m as d}from"./chunks/framework.8JjYC3xy.js";const g=JSON.parse('{"title":"第一章：Claude Code 是什么","description":"了解 Claude Code 的基本概念、使用场景，以及在中国大陆怎么用","frontmatter":{"title":"第一章：Claude Code 是什么","description":"了解 Claude Code 的基本概念、使用场景，以及在中国大陆怎么用","lastVerified":"2026-02-24","officialDoc":"https://code.claude.com/docs/zh-CN/overview"},"headers":[],"relativePath":"guide/1-getting-started/1-what-is-claude-code.md","filePath":"guide/1-getting-started/1-what-is-claude-code.md"}'),l={name:"guide/1-getting-started/1-what-is-claude-code.md"};function r(i,t,s,n,c,h){return o(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="第一章-claude-code-是什么" tabindex="-1">第一章：Claude Code 是什么 <a class="header-anchor" href="#第一章-claude-code-是什么" aria-label="Permalink to &quot;第一章：Claude Code 是什么&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">学习目标</p><p>学完这章，你会理解 Claude Code 能做什么、不能做什么，以及在国内用什么方式才能用上它。</p></div><h2 id="它是住在你电脑里的-ai-不是一个网页" tabindex="-1">它是住在你电脑里的 AI，不是一个网页 <a class="header-anchor" href="#它是住在你电脑里的-ai-不是一个网页" aria-label="Permalink to &quot;它是住在你电脑里的 AI，不是一个网页&quot;">​</a></h2><p>Claude Code 是 Anthropic 出的 AI 编程助手。和网页版聊天最大的区别：<strong>它直接在你的电脑上干活</strong>——读你的文件、改你的代码、运行命令。</p><table tabindex="0"><thead><tr><th></th><th>网页版 Claude（claude.ai）</th><th>Claude Code</th></tr></thead><tbody><tr><td>在哪运行</td><td>浏览器</td><td>你自己的电脑</td></tr><tr><td>能看什么</td><td>你粘贴给它的内容</td><td>整个项目文件夹</td></tr><tr><td>能做什么</td><td>回答、写作、分析</td><td>直接读写文件、跑命令、改代码</td></tr><tr><td>适合</td><td>一问一答</td><td>需要多步骤、要动真文件的活</td></tr></tbody></table><h2 id="四种打开方式-从最简单的开始" tabindex="-1">四种打开方式，从最简单的开始 <a class="header-anchor" href="#四种打开方式-从最简单的开始" aria-label="Permalink to &quot;四种打开方式，从最简单的开始&quot;">​</a></h2><p>Claude Code 现在不止一种形态，你按自己的习惯选一个就行：</p><ol><li><strong>终端（CLI）</strong> — 本教程的主角。一个黑框框，打字对话。功能最全，所有新特性都先出现在这里</li><li><strong>桌面应用</strong> — 装个 App，有图形界面，能同时开多个会话，不用记命令</li><li><strong>VS Code / JetBrains 插件</strong> — 在编辑器里直接用，改动直接显示成 diff</li><li><strong>网页版（云端）</strong> — 浏览器里跑，不用装任何东西，适合临时任务</li></ol><p>本教程以<strong>终端</strong>为主，因为它的概念最通用：学会终端，其他几种形态基本不用重新学。</p><h2 id="claude-code-能做什么" tabindex="-1">Claude Code 能做什么？ <a class="header-anchor" href="#claude-code-能做什么" aria-label="Permalink to &quot;Claude Code 能做什么？&quot;">​</a></h2><p>它是一个 AI 编程助手，但能做的事远不止编程。</p><h3 id="编程相关" tabindex="-1">编程相关 <a class="header-anchor" href="#编程相关" aria-label="Permalink to &quot;编程相关&quot;">​</a></h3><ul><li><strong>读代码</strong>：帮你理解一个陌生项目的结构</li><li><strong>写代码</strong>：创建新文件或修改现有代码</li><li><strong>解释代码</strong>：用自然语言解释代码在做什么</li><li><strong>调试问题</strong>：帮你找出 bug 并修复</li><li><strong>审查代码</strong>：<code>/code-review</code> 直接检查你的改动</li><li><strong>辅助 Git</strong>：写 commit message、处理合并冲突、解释别人的改动</li></ul><h3 id="文档编辑" tabindex="-1">文档编辑 <a class="header-anchor" href="#文档编辑" aria-label="Permalink to &quot;文档编辑&quot;">​</a></h3><p>Claude Code 擅长处理各种文档工作：</p><ul><li><strong>Word 文档</strong>：写报告、写文档、润色文字、总结内容</li><li><strong>Excel 表格</strong>：分析数据、写公式、生成图表</li><li><strong>PPT 制作</strong>：规划演示结构、写内容、调整格式</li><li><strong>Markdown 写作</strong>：写博客、写文档、写邮件（.md 是它最顺手的格式）</li></ul><h3 id="日常重复性工作" tabindex="-1">日常重复性工作 <a class="header-anchor" href="#日常重复性工作" aria-label="Permalink to &quot;日常重复性工作&quot;">​</a></h3><ul><li><strong>批量重命名文件</strong>：按规则批量改文件名</li><li><strong>整理文件夹</strong>：自动归类、移动、清理重复文件</li><li><strong>批量生成文本</strong>：报告、邮件、模板内容</li><li><strong>数据格式转换</strong>：CSV 转 JSON、Excel 转数据库格式</li><li><strong>日志分析</strong>：从大量日志里提取关键信息</li></ul><div class="tip custom-block"><p class="custom-block-title">小技巧</p><p>由于 Claude Code 能直接读写你的电脑文件，它特别适合需要<strong>批量处理</strong>或<strong>多步骤自动化</strong>的任务。这类活网页版 Claude 做不了，因为它碰不到你的硬盘。</p></div><h2 id="在中国大陆怎么用上它" tabindex="-1">在中国大陆怎么用上它 <a class="header-anchor" href="#在中国大陆怎么用上它" aria-label="Permalink to &quot;在中国大陆怎么用上它&quot;">​</a></h2><p>这一步很多人卡住，先说清楚。Claude Code 本身是免费软件，但<strong>用起来需要一个能调用 Claude 模型的账号</strong>，有两条路：</p><table tabindex="0"><thead><tr><th>方式</th><th>门槛</th><th>适合谁</th></tr></thead><tbody><tr><td><strong>官方账号</strong>（Claude Pro/Max 订阅，或 Anthropic API Key）</td><td>需要海外支付方式 + 网络能连上 Anthropic</td><td>有海外信用卡、或有稳定网络的同学</td></tr><tr><td><strong>第三方 API 中转</strong>（国内中转服务商）</td><td>支付宝/微信付款即可，网络直连</td><td>大部分国内用户</td></tr></tbody></table><p>本站<strong>第三章</strong>会详细讲第二条路（用中转服务商），因为对国内用户门槛最低。如果你已经有官方订阅，装完直接运行 <code>claude</code> 按提示登录就行，可以跳过第三章。</p><div class="warning custom-block"><p class="custom-block-title">别被这件事劝退</p><p>账号配置只做一次，十分钟的事。真正需要学的是后面怎么和它对话、怎么让它干活。先花十分钟配好，剩下的都是收益。</p></div><h2 id="claude-code-不能做什么" tabindex="-1">Claude Code 不能做什么？ <a class="header-anchor" href="#claude-code-不能做什么" aria-label="Permalink to &quot;Claude Code 不能做什么？&quot;">​</a></h2><ul><li><strong>不能替你做决定</strong>：最终决策权在你手里</li><li><strong>不会读心术</strong>：你需要清楚地描述你要什么</li><li><strong>复杂 Excel/PPT 有上限</strong>：基本编辑没问题，复杂格式和宏还是要你自己调整</li><li><strong>不能保证 100% 正确</strong>：它会犯错，尤其是它看不到的信息（比如你脑子里的部署流程）。看到改动先看一眼 diff 再接受</li></ul><div class="tip custom-block"><p class="custom-block-title">关于&quot;操作确认&quot;</p><p>早期版本的 Claude Code 每一步都要你点确认。现在默认是<strong>自动模式</strong>（auto mode）：安全操作（读文件、跑测试）自动放行，危险操作（删文件、push 到远端）仍会被拦下问你。你随时可以按 <code>Shift + Tab</code> 切换这个行为。详见第十七章。</p></div><h2 id="和-chatgpt-copilot-的区别" tabindex="-1">和 ChatGPT / Copilot 的区别 <a class="header-anchor" href="#和-chatgpt-copilot-的区别" aria-label="Permalink to &quot;和 ChatGPT / Copilot 的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>特点</th><th>适合场景</th></tr></thead><tbody><tr><td>ChatGPT / Claude 网页版</td><td>网页聊天，什么都能问</td><td>通用问答、写文章、分析数据</td></tr><tr><td>Copilot</td><td>IDE 插件，边写边补全</td><td>写代码时逐行补全</td></tr><tr><td>Claude Code</td><td>在项目里工作的 AI，能读写文件、跑命令</td><td>理解整个项目、批量改代码、自动化</td></tr></tbody></table><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q: Claude Code 要钱吗？</strong></p><p>A: 软件免费。要花钱的是模型调用：官方订阅按月付费，中转服务商按量付费（通常几块钱起步就能试）。</p><p><strong>Q: 不会命令行能学吗？</strong></p><p>A: 能。本教程从零教你终端的基本用法，真正要记的命令不到 10 个。</p><p><strong>Q: 我的电脑配置够吗？</strong></p><p>A: 够。它不占本地算力，所有推理都在云端。任何能上网的 Mac / Windows / Linux 电脑都能跑。</p><p><strong>Q: 会不会把我代码搞坏？</strong></p><p>A: 有两个保险：一是它改动前会显示 diff，二是 <code>/rewind</code> 能把代码和对话回滚到之前任意一个检查点。</p><h2 id="下一章" tabindex="-1">下一章 <a class="header-anchor" href="#下一章" aria-label="Permalink to &quot;下一章&quot;">​</a></h2><p><a href="/claude-code-guide/guide/1-getting-started/2-installation.html">👉 第二章：安装 Claude Code</a></p>',40)])])}const p=a(l,[["render",r]]);export{g as __pageData,p as default};
